package local.tv.quranidle;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.database.ContentObserver;import android.provider.Settings;import android.util.Log;
public class IdleService extends Service {
 private PrayerNotice prayerNotice;
 private final Handler h=new Handler(Looper.getMainLooper());private AudioManager audio;private MediaPlayer player;private AudioFocusRequest focus;private boolean ownFocus,session;private int previous=-1,applied=-1;private static final String TAG="QuranIdle";
 private void state(String s){Log.i(TAG,s);getSharedPreferences("state",0).edit().putString("last",s).putLong("at",System.currentTimeMillis()).apply();}
 private final BroadcastReceiver events=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String a=i.getAction();if(Intent.ACTION_DREAMING_STARTED.equals(a)){state("dream-start");play(false);}else{state("dream-end-or-screen-off");stopAudio();}}};
 private final ContentObserver volumeObserver=new ContentObserver(h){public void onChange(boolean self){cap();PrayerGuard.enforce(IdleService.this);}};
 private final Runnable limiter=new Runnable(){public void run(){if(session){cap();h.postDelayed(this,500);}}};
 public void onCreate(){super.onCreate();audio=(AudioManager)getSystemService(AUDIO_SERVICE);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("idle","التلاوة عند الخمول",NotificationManager.IMPORTANCE_LOW));Intent open=new Intent(this,MainActivity.class);Notification n=new Notification.Builder(this,"idle").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("التلاوة عند الخمول مفعّلة").setContentText("البقرة — ماهر المعيقلي — الصوت حتى ٧").setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE)).build();startForeground(1,n);
 IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_DREAMING_STARTED);f.addAction(Intent.ACTION_DREAMING_STOPPED);f.addAction(Intent.ACTION_SCREEN_OFF);registerReceiver(events,f,Context.RECEIVER_EXPORTED);getContentResolver().registerContentObserver(Settings.System.CONTENT_URI,true,volumeObserver);state("armed");prayerNotice=new PrayerNotice(this);prayerNotice.refresh();}
 public int onStartCommand(Intent i,int flags,int id){if(!getSharedPreferences("state",0).getBoolean("enabled",false)){stopSelf();return START_NOT_STICKY;}if(i!=null&&"test".equals(i.getAction()))play(true);if(prayerNotice!=null)prayerNotice.check();if(i!=null&&"adhan-test".equals(i.getAction())&&prayerNotice!=null)prayerNotice.testAdhan();if(i!=null&&"prayer-test".equals(i.getAction())&&prayerNotice!=null)prayerNotice.preview();return START_STICKY;}
 private void cap(){if(session){int v=audio.getStreamVolume(AudioManager.STREAM_MUSIC),max=Math.min(7,audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC));if(v>max){audio.setStreamVolume(AudioManager.STREAM_MUSIC,max,0);applied=max;}}}
 private void play(boolean test){if(PrayerGuard.active(this))return;if(session)return;if(audio.isMusicActive()){state("skipped-existing-media");return;}session=true;previous=audio.getStreamVolume(AudioManager.STREAM_MUSIC);applied=Math.min(previous,Math.min(7,audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)));audio.setStreamVolume(AudioManager.STREAM_MUSIC,applied,0);
 AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attrs).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)stopAudio();}).build();ownFocus=audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;if(!ownFocus){state("no-audio-focus");stopAudio();return;}
 try{player=new MediaPlayer();player.setAudioAttributes(attrs);player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource("https://cdn.mp3quran.net/audio/maher-muaiqly/r1/002.mp3");player.setOnPreparedListener(p->{if(session&&p==player){cap();p.start();state("playing-baqarah-maher-volume-"+audio.getStreamVolume(AudioManager.STREAM_MUSIC));}});player.setOnCompletionListener(p->{state("completed");stopAudio();});player.setOnErrorListener((p,w,e)->{state("playback-error-"+w+"-"+e);stopAudio();return true;});player.prepareAsync();h.post(limiter);if(test)h.postDelayed(()->{state("test-finished");stopAudio();},20000);else h.postDelayed(()->{if(session&&player!=null){try{if(!player.isPlaying()){state("prepare-timeout");stopAudio();}}catch(Exception ignored){stopAudio();}}},60000);}catch(Exception e){state("error-"+e.getClass().getSimpleName());stopAudio();}}
 private void stopAudio(){session=false;h.removeCallbacksAndMessages(null);if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}if(ownFocus&&focus!=null)audio.abandonAudioFocusRequest(focus);ownFocus=false;focus=null;if(previous>=0&&applied>=0&&audio.getStreamVolume(AudioManager.STREAM_MUSIC)==applied)audio.setStreamVolume(AudioManager.STREAM_MUSIC,previous,0);previous=-1;applied=-1;}
 public void onDestroy(){if(prayerNotice!=null)prayerNotice.close();stopAudio();unregisterReceiver(events);getContentResolver().unregisterContentObserver(volumeObserver);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
